package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The people kept on a sheet, in the order they were added. A name is stored without surrounding
 * spaces and is unique on its sheet regardless of case. An edit is made from a version of the
 * person; once someone else has saved the person since, it is refused.
 */
@Service
public class PersonService {

    private static final int MAX_NAME = 100;
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        sheets.load(sheetId, user);
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
            throw nameInUse();
        }
        Person person = people.save(new Person(sheetId, trimmed, grade));
        audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
        return person;
    }

    /** A line of an import that breaks a rule: its number (from 1) and why. */
    public record ImportError(int line, String message) {
    }

    /**
     * How many people an import added and how many existing ones it updated, or the lines that
     * stopped it (then nothing is changed).
     */
    public record ImportResult(int added, int updated, List<ImportError> errors) {
    }

    /**
     * Import people from lines of name,grade. Every line is checked first with the rules of the form;
     * a name repeated in the paste is compared like uniqueness on the sheet. If any line breaks a
     * rule nothing is changed; otherwise, in order, a name already on the sheet has its grade
     * updated and any other name is added. Blank lines are skipped.
     */
    @Transactional
    public ImportResult importPeople(String sheetId, String user, String text) {
        String[] lines = text.split("\\r?\\n", -1);
        List<ImportError> errors = new ArrayList<>();
        List<String[]> rows = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (line.isBlank()) {
                continue;
            }
            int number = i + 1;
            int comma = line.lastIndexOf(',');
            String name = (comma < 0 ? line : line.substring(0, comma)).trim();
            String grade = comma < 0 ? "" : line.substring(comma + 1).trim();
            String error = null;
            if (name.isEmpty()) {
                error = "Enter a name.";
            } else if (name.length() > MAX_NAME) {
                error = "The name is too long.";
            } else if (!GRADES.contains(grade)) {
                error = "The grade must be A, B or C.";
            } else if (!seen.add(name.toLowerCase(Locale.ROOT))) {
                error = "That name is repeated in the import.";
            }
            if (error != null) {
                errors.add(new ImportError(number, error));
            } else {
                rows.add(new String[] {name, grade});
            }
        }
        if (!errors.isEmpty()) {
            return new ImportResult(0, 0, errors);
        }
        if (!rows.isEmpty()) {
            sheets.load(sheetId, user);
        }
        int added = 0;
        int updated = 0;
        for (String[] row : rows) {
            Optional<Person> existing = people.findFirstBySheetIdAndNameIgnoreCase(sheetId, row[0]);
            if (existing.isPresent()) {
                Person person = existing.get();
                person.setGrade(row[1]);
                person = people.saveAndFlush(person);
                audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
                updated++;
            } else {
                Person person = people.save(new Person(sheetId, row[0], row[1]));
                audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
                added++;
            }
        }
        return new ImportResult(added, updated, List.of());
    }

    @Transactional
    public Person update(String sheetId, String user, Long personId, long version, String name, String grade) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getVersion() != version) {
            throw changedMeanwhile();
        }
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, personId)) {
            throw nameInUse();
        }
        person.setName(trimmed);
        person.setGrade(grade);
        try {
            person = people.saveAndFlush(person);
        } catch (OptimisticLockingFailureException e) {
            throw changedMeanwhile();
        }
        audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
        return person;
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Person changed since it was loaded");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one record for a change to a sheet: the event, then sheet=&lt;id&gt; and by=&lt;user&gt;, then
     * the fields, separated by single spaces. Inside a transaction the record is written only once
     * it commits, so a change that is refused or rolled back writes nothing.
     */
    public void change(String event, String sheetId, String user, String... fields) {
        StringBuilder entry = new StringBuilder(event).append(" sheet=").append(sheetId).append(" by=").append(user);
        for (String field : fields) {
            entry.append(' ').append(field);
        }
        String line = entry.toString();
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCommit() {
                    record(line);
                }
            });
        } else {
            record(line);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
-- People on a sheet, listed in the order they were added (by id). The grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- The version of a person, raised each time the person is saved, so an edit made from an
-- out-of-date copy is refused.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

export interface Person {
  id: number;
  name: string;
  grade: Grade;
  /** Raised each time the person is saved; an edit sends back the version it was made from. */
  version: number;
}

export interface PersonFields {
  name: string;
  grade: Grade;
}

/**
 * What an import did: how many it added and how many existing people it updated, or the lines
 * (numbered from 1) that stopped it.
 */
export interface ImportResult {
  added: number;
  updated: number;
  errors: { line: number; message: string }[];
}

// The people kept on the active sheet, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class PeopleApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(): Promise<Person[]> {
    return firstValueFrom(this.http.get<Person[]>(this.url(), { headers: this.headers() }));
  }

  add(fields: PersonFields): Promise<Person> {
    return firstValueFrom(this.http.post<Person>(this.url(), fields, { headers: this.headers() }));
  }

  /**
   * Add or update people from pasted lines of name,grade; all of them, or none when any line is bad.
   */
  importLines(text: string): Promise<ImportResult> {
    return firstValueFrom(
      this.http.post<ImportResult>(`${this.url()}/import`, { text }, { headers: this.headers() }),
    );
  }

  /** Refused with 412 when someone else has saved the person since this version was read. */
  update(id: number, version: number, fields: PersonFields): Promise<Person> {
    return firstValueFrom(
      this.http.put<Person>(`${this.url()}/${id}`, { ...fields, version }, { headers: this.headers() }),
    );
  }

  private url(): string {
    const id = this.session.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return `/api/sheets/${encodeURIComponent(id)}/people`;
  }

  private headers(): Record<string, string> {
    const user = this.session.user();
    if (!user) throw new Error('not signed in');
    return { 'X-User': user };
  }
}
