        .all()
        .filter((c) => c.personId === p.id && counts(c))
        .map((c) => this.rates.dueOf(c, p.grade))
        .filter((c) => c !== undefined);
      if (figures.length > 0 || this.rates.byGrade().has(p.grade)) {
        out.set(p.id, figures.reduce((sum, c) => sum + c, 0));
      }
    }
    return out;
  });

