302	        Person person = people.findByIdAndSheetId(personId, sheetId)
303	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
304	        if (person.getVersion() != version) {
305	            throw changedMeanwhile();
306	        }
307	        String trimmed = name.trim();
308	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, personId)) {
309	            throw nameInUse();
310	        }
311	        person.setName(trimmed);
312	        person.setGrade(grade);
313	        try {
314	            person = people.saveAndFlush(person);
315	        } catch (OptimisticLockingFailureException e) {
316	            throw changedMeanwhile();
317	        }
318	        audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
319	        return person;
320	    }
321	
322	    private static ResponseStatusException changedMeanwhile() {
323	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Person changed since it was loaded");
324	    }
325	
326	    private static ResponseStatusException nameInUse() {
327	        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
328	    }
329	}
330	package net.officefloor.hq.app;
331	
332	import java.io.IOException;
333	import java.io.UncheckedIOException;
334	import java.nio.charset.StandardCharsets;
335	import java.nio.file.Files;
336	import java.nio.file.Path;
337	import java.nio.file.StandardOpenOption;
338	import org.springframework.beans.factory.annotation.Value;
339	import org.springframework.stereotype.Service;
340	import org.springframework.transaction.support.TransactionSynchronization;
341	import org.springframework.transaction.support.TransactionSynchronizationManager;
342	
343	/**
344	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
345	 * so tests can assert side-effects by reading that file — the second test-assertion channel
346	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
347	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
348	 *
349	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
350	 * SYNC) so a test reads the record immediately.
351	 */
352	@Service
353	public class Audit {
354	
355	    private final Path file;
356	
357	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
358	        this.file = Path.of(path);
359	    }
360	
361	    /** Append one audit record. Tests assert the exact line(s) in the file. */
362	    public synchronized void record(String entry) {
363	        try {
364	            Path parent = file.toAbsolutePath().getParent();
365	            if (parent != null) {
366	                Files.createDirectories(parent);
367	            }
368	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
369	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
370	        } catch (IOException e) {
371	            throw new UncheckedIOException(e);
372	        }
373	    }
374	
375	    /**
376	     * Append one record for a change to a sheet: the event, then sheet=&lt;id&gt; and by=&lt;user&gt;, then
377	     * the fields, separated by single spaces. Inside a transaction the record is written only once
378	     * it commits, so a change that is refused or rolled back writes nothing.
379	     */
380	    public void change(String event, String sheetId, String user, String... fields) {
381	        StringBuilder entry = new StringBuilder(event).append(" sheet=").append(sheetId).append(" by=").append(user);
382	        for (String field : fields) {
383	            entry.append(' ').append(field);
384	        }
385	        String line = entry.toString();
386	        if (TransactionSynchronizationManager.isSynchronizationActive()) {
387	            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
388	                @Override
389	                public void afterCommit() {
390	                    record(line);
391	                }
392	            });
393	        } else {
394	            record(line);
395	        }
396	    }
397	
398	    /** Truncate the audit file. */
399	    public synchronized void clear() {
400	        try {
401	            Files.deleteIfExists(file);
402	        } catch (IOException e) {
403	            throw new UncheckedIOException(e);
404	        }
405	    }
406	}
407	-- People on a sheet, listed in the order they were added (by id). The grade is one of A, B or C.
408	CREATE TABLE person (
409	    id       BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
410	    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
411	    name     VARCHAR(100) NOT NULL,
412	    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
413	);
414	CREATE INDEX person_sheet ON person (sheet_id, id);
415	-- The version of a person, raised each time the person is saved, so an edit made from an
416	-- out-of-date copy is refused.
417	ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
418	import { HttpClient } from '@angular/common/http';
419	import { Injectable, inject } from '@angular/core';
420	import { firstValueFrom } from 'rxjs';
421	import { Session } from './session';
422	
423	export type Grade = 'A' | 'B' | 'C';
424	export const GRADES: readonly Grade[] = ['A', 'B', 'C'];
425	
426	export interface Person {
427	  id: number;
428	  name: string;
429	  grade: Grade;
430	  /** Raised each time the person is saved; an edit sends back the version it was made from. */
431	  version: number;
432	}
433	
434	export interface PersonFields {
435	  name: string;
436	  grade: Grade;
437	}
438	
439	/**
440	 * What an import did: how many it added and how many existing people it updated, or the lines
441	 * (numbered from 1) that stopped it.
442	 */
443	export interface ImportResult {
444	  added: number;
445	  updated: number;
446	  errors: { line: number; message: string }[];
447	}
448	
449	// The people kept on the active sheet, read from and written to the store.
450	@Injectable({ providedIn: 'root' })
451	export class PeopleApi {
452	  private readonly http = inject(HttpClient);
453	  private readonly session = inject(Session);
454	
455	  list(): Promise<Person[]> {
456	    return firstValueFrom(this.http.get<Person[]>(this.url(), { headers: this.headers() }));
457	  }
458	
459	  add(fields: PersonFields): Promise<Person> {
460	    return firstValueFrom(this.http.post<Person>(this.url(), fields, { headers: this.headers() }));
461	  }
462	
463	  /**
464	   * Add or update people from pasted lines of name,grade; all of them, or none when any line is bad.
465	   */
466	  importLines(text: string): Promise<ImportResult> {
467	    return firstValueFrom(
468	      this.http.post<ImportResult>(`${this.url()}/import`, { text }, { headers: this.headers() }),
469	    );
470	  }
471	
472	  /** Refused with 412 when someone else has saved the person since this version was read. */
473	  update(id: number, version: number, fields: PersonFields): Promise<Person> {
474	    return firstValueFrom(
475	      this.http.put<Person>(`${this.url()}/${id}`, { ...fields, version }, { headers: this.headers() }),
476	    );
477	  }
478	
479	  private url(): string {
480	    const id = this.session.sheetId();
481	    if (!id) throw new Error('no sheet loaded');
482	    return `/api/sheets/${encodeURIComponent(id)}/people`;
483	  }
484	
485	  private headers(): Record<string, string> {
486	    const user = this.session.user();
487	    if (!user) throw new Error('not signed in');
488	    return { 'X-User': user };
489	  }
490	}
491	import { HttpErrorResponse } from '@angular/common/http';
492	import { Component, computed, effect, inject, signal, untracked } from '@angular/core';
493	import { AMOUNT, Claims, counts, formatCents } from '../../core/claims';
494	import { GRADES, Grade, ImportResult, PeopleApi, Person } from '../../core/people';
495	import { Periods } from '../../core/periods';
496	import { Rates } from '../../core/rates';
497	import { Session } from '../../core/session';
498	import { PersonClaims } from '../claims/claims';
499	import { PeriodsPanel } from '../periods/periods';
500	
501	// The sheet's people, in the order they were added, and the one form that adds a person or edits
502	// an existing one.
503	@Component({
504	  selector: 'app-people',
505	  imports: [PersonClaims, PeriodsPanel],
506	  template: `
507	    <section aria-labelledby="people-heading">
508	      <h2 id="people-heading">People</h2>
509	
510	      <form (submit)="save($event)">
511	        <label for="person-name">Name</label>
512	        <input
513	          id="person-name"
514	          data-testid="person-form-name"
515	          [value]="name()"
516	          (input)="name.set($any($event.target).value); error.set(null)"
517	        />
518	        <label for="person-grade">Grade</label>
519	        <select
520	          id="person-grade"
521	          data-testid="person-form-grade"
522	          [value]="grade()"
523	          (change)="grade.set($any($event.target).value); error.set(null)"
524	        >
525	          @for (g of grades; track g) {
526	            <option [value]="g" [selected]="g === grade()">{{ g }}</option>
527	          }
528	        </select>
529	        <button type="submit" data-testid="person-form-submit">
530	          {{ editingId() === null ? 'Add person' : 'Save person' }}
531	        </button>
532	        @if (editingId() !== null) {
533	          <button type="button" data-testid="person-form-cancel" (click)="reset()">Cancel</button>
534	        }
535	        @if (error(); as err) {
536	          <p role="alert" data-testid="person-form-error">{{ err }}</p>
537	        }
538	      </form>
539	
540	      <form (submit)="importPeople($event)">
541	        <label for="import-text">Import people (one name,grade per line)</label>
542	        <textarea
543	          id="import-text"
544	          data-testid="import-text"
545	          rows="4"
546	          [value]="importText()"
547	          (input)="importText.set($any($event.target).value); importResult.set(null); importError.set(null)"
548	        ></textarea>
549	        <button type="submit" data-testid="import-submit">Import</button>
550	        @if (importResult(); as result) {
551	          <div role="status">
552	            <p>Added <strong data-testid="import-added">{{ result.added }}</strong></p>
553	            <p>Updated <strong data-testid="import-updated">{{ result.updated }}</strong></p>
554	            @if (result.errors.length > 0) {
555	              <p>Nothing was imported; fix these lines:</p>
556	              <ul>
557	                @for (e of result.errors; track e.line) {
558	                  <li [attr.data-testid]="'import-error-' + e.line">Line {{ e.line }}: {{ e.message }}</li>
559	                }
560	              </ul>
561	            }
562	          </div>
563	        }
564	        @if (importError(); as err) {
565	          <p role="alert" data-testid="import-error">{{ err }}</p>
566	        }
567	      </form>
568	
569	      <form (submit)="quickAdd($event)" aria-label="Quick add a claim">
570	        <label for="quick-name">Name</label>
571	        <input
572	          id="quick-name"
573	          data-testid="quick-name"
574	          [value]="quickName()"
575	          (input)="quickName.set($any($event.target).value); quickError.set(null)"
576	        />
577	        <label for="quick-amount">Amount</label>
578	        <input
579	          id="quick-amount"
580	          data-testid="quick-amount"
581	          inputmode="decimal"
582	          [value]="quickAmount()"
583	          (input)="quickAmount.set($any($event.target).value); quickError.set(null)"
584	        />
585	        <button type="submit" data-testid="quick-submit">Quick add claim</button>
586	        @if (quickError(); as err) {
587	          <p role="alert" data-testid="quick-error">{{ err }}</p>
588	        }
589	      </form>
590	
591	      <table>
592	        <thead>
593	          <tr><th scope="col">Name</th><th scope="col">Grade</th><th scope="col">Claimed</th><th scope="col">Due</th><th scope="col">Claims</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr>
594	        </thead>
595	        <tbody>
596	          @for (p of people(); track p.id) {
597	            <tr [attr.data-testid]="'person-row-' + p.id">
598	              <td data-testid="person-name">{{ p.name }}</td>
599	              <td data-testid="person-grade">{{ p.grade }}</td>
600	              <td data-testid="person-claimed">{{ claimed(p.id) }}</td>
601	              <td data-testid="person-due-total">{{ dueTotal(p) }}</td>
602	              <td><app-person-claims [personId]="p.id" [personName]="p.name" [grade]="p.grade" /></td>
603	              <td>
604	                <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="edit(p)">
605	                  Edit<span class="visually-hidden"> {{ p.name }}</span>
606	                </button>
607	              </td>
608	            </tr>
609	          }
610	        </tbody>
611	      </table>
612	
613	      <p>Claimed total <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
614	      <p>Due total <strong data-testid="rollup-due-total">{{ dueTotalAll() }}</strong></p>
615	
616	      <app-periods [people]="people()" />
617	    </section>
618	  `,
619	})
620	export class People {
621	  private readonly api = inject(PeopleApi);
622	  private readonly session = inject(Session);
623	  private readonly claims = inject(Claims);
624	  private readonly rates = inject(Rates);
625	  private readonly periods = inject(Periods);
626	
627	  protected readonly grades = GRADES;
628	  protected readonly people = signal<Person[]>([]);
629	  protected readonly name = signal('');
630	  protected readonly grade = signal<Grade>('A');
631	  protected readonly editingId = signal<number | null>(null);
632	  /** The version of the person the editor loaded. */
633	  private editingVersion = 0;
634	  /** Set while a submit awaits the store, so a second submit does not store a second record. */
635	  private saving = false;
636	  protected readonly error = signal<string | null>(null);
637	  protected readonly importText = signal('');
638	  protected readonly importResult = signal<ImportResult | null>(null);
639	  protected readonly importError = signal<string | null>(null);
640	  /** Set while an import awaits the store, so a second submit does not import twice. */
641	  private importing = false;
642	  protected readonly quickName = signal('');
643	  protected readonly quickAmount = signal('');
644	  protected readonly quickError = signal<string | null>(null);
645	  /** Set while a quick add awaits the store, so a second submit does not store a second claim. */
646	  private quickAdding = false;
647	  protected readonly claimedTotal = computed(() => formatCents(this.claims.totalCents()));
648	
649	  /**
650	   * Each person's due-total in cents, by person id: the sum of their counted claims' due figures as
651	   * shown (each already rounded), skipping those that are n/a. Absent when none has a figure and
652	   * their grade has no rate today.
653	   */
654	  private readonly dueCents = computed(() => {
655	    const out = new Map<number, number>();
656	    for (const p of this.people()) {
657	      const figures = this.claims
658	        .all()
659	        .filter((c) => c.personId === p.id && counts(c))
660	        .map((c) => this.rates.dueOf(c, p.grade))
661	        .filter((c) => c !== undefined);
662	      if (figures.length > 0 || this.rates.byGrade().has(p.grade)) {
663	        out.set(p.id, figures.reduce((sum, c) => sum + c, 0));
664	      }
665	    }
666	    return out;
667	  });
668	
669	  /** Everyone's due-total added up, skipping those that are n/a. */
670	  protected readonly dueTotalAll = computed(() =>
671	    formatCents([...this.dueCents().values()].reduce((sum, c) => sum + c, 0)),
672	  );
673	
674	  constructor() {
675	    // Re-read the store each time the sheet is (re-)loaded.
676	    effect(() => {
677	      this.session.loads();
678	      untracked(() => {
679	        this.reset();
680	        this.importText.set('');
681	        this.importResult.set(null);
682	        this.importError.set(null);
683	        this.quickName.set('');
684	        this.quickAmount.set('');
685	        this.quickError.set(null);
686	        void this.reload();
687	        void this.claims.reload();
688	      });
689	    });
690	  }
691	
692	  protected claimed(personId: number): string {
693	    return formatCents(this.claims.claimedCents().get(personId) ?? 0);
694	  }
695	
696	  protected dueTotal(person: Person): string {
697	    const cents = this.dueCents().get(person.id);
698	    return cents === undefined ? 'n/a' : formatCents(cents);
699	  }
700	
701	  protected edit(person: Person): void {
702	    this.editingId.set(person.id);
703	    this.editingVersion = person.version;
704	    this.name.set(person.name);
705	    this.grade.set(person.grade);
706	    this.error.set(null);
707	  }
708	
709	  protected reset(): void {
710	    this.editingId.set(null);
711	    this.name.set('');
712	    this.grade.set('A');
713	    this.error.set(null);
714	  }
715	
716	  protected async save(event: Event): Promise<void> {
717	    event.preventDefault();
718	    if (this.saving) return;
719	    this.error.set(null);
720	    const fields = { name: this.name(), grade: this.grade() };
721	    if (!fields.name.trim()) {
722	      this.error.set('Enter a name.');
723	      return;
724	    }
725	    const id = this.editingId();
726	    this.saving = true;
727	    try {
728	      if (id === null) {
729	        const added = await this.api.add(fields);
730	        this.people.update((list) => [...list, added]);
731	      } else {
732	        const saved = await this.api.update(id, this.editingVersion, fields);
733	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
734	      }
735	      this.reset();
736	    } catch (e) {
737	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
738	        await this.showCurrent(id);
739	        this.error.set('Someone else saved this person since you opened it. Their values are shown; open it again to edit.');
740	        return;
741	      }
742	      if (e instanceof HttpErrorResponse && e.status === 409) {
743	        this.error.set('That name is already in use on this sheet.');
744	        return;
745	      }
746	      this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
747	    } finally {
748	      this.saving = false;
749	    }
750	  }
751	
752	  protected async importPeople(event: Event): Promise<void> {
753	    event.preventDefault();
754	    if (this.importing) return;
755	    this.importResult.set(null);
756	    this.importError.set(null);
757	    this.importing = true;
758	    try {
759	      const result = await this.api.importLines(this.importText());
760	      this.importResult.set(result);
761	      if (result.added > 0 || result.updated > 0) {
762	        this.importText.set('');
763	        await this.reload();
764	      }
765	    } catch {
766	      this.importError.set('The people could not be imported.');
767	    } finally {
768	      this.importing = false;
769	    }
770	  }
771	
772	  /**
773	   * Add a DRAFT claim dated the sheet's today for the named person, adding the person (grade A)
774	   * first when the name is not on the sheet; the rules of the person and claim forms apply.
775	   */
776	  protected async quickAdd(event: Event): Promise<void> {
777	    event.preventDefault();
778	    if (this.quickAdding) return;
779	    this.quickError.set(null);
780	    const name = this.quickName().trim();
781	    const amount = this.quickAmount().trim();
782	    if (!name) {
783	      this.quickError.set('Enter a name.');
784	      return;
785	    }
786	    if (name.length > 100) {
787	      this.quickError.set('The name is too long.');
788	      return;
789	    }
790	    if (!AMOUNT.test(amount)) {
791	      this.quickError.set('Enter an amount of 0.00 or more, with at most two decimals.');
792	      return;
793	    }
794	    if (this.periods.closedOn(this.session.today() ?? '')) {
795	      this.quickError.set('Today is in a closed period, so no claim can be added.');
796	      return;
797	    }
798	    this.quickAdding = true;
799	    try {
800	      const added = await this.claims.quickAdd(name, amount);
801	      if (!this.people().some((p) => p.id === added.personId)) await this.reload();
802	      this.quickName.set('');
803	      this.quickAmount.set('');
804	    } catch (e) {
805	      this.quickError.set(e instanceof HttpErrorResponse && e.status === 423
806	        ? 'Today is in a closed period, so no claim can be added.'
807	        : 'The claim could not be added.');
808	    } finally {
809	      this.quickAdding = false;
810	    }
811	  }
812	
813	  /** Re-read the store and show the person's current values in the form and in their row. */
814	  private async showCurrent(id: number): Promise<void> {
815	    await this.reload();
816	    const current = this.people().find((p) => p.id === id);
817	    if (current) {
818	      this.name.set(current.name);
819	      this.grade.set(current.grade);
820	    }
821	  }
822	
823	  private async reload(): Promise<void> {
824	    try {
825	      this.people.set(await this.api.list());
826	    } catch {
827	      this.people.set([]);
828	    }
829	  }
830	}
