17	import org.springframework.transaction.annotation.Transactional;
18	import org.springframework.web.server.ResponseStatusException;
19	
20	/**
21	 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
22	 * missing note is stored empty. Only a DRAFT claim can be edited (409); an open claim is changed by
23	 * voiding it and adding a new one. No claim dated in a closed period can be added, edited or change
24	 * status (423).
25	 */
26	@Service
27	public class ClaimService {
28	
29	    private final ClaimRepository claims;
30	    private final PersonRepository people;
31	    private final PeriodRepository periods;
32	    private final RateService rates;
33	    private final SheetService sheets;
34	    private final Audit audit;
35	
36	    public ClaimService(ClaimRepository claims, PersonRepository people, PeriodRepository periods, RateService rates,
37	            SheetService sheets, Audit audit) {
38	        this.claims = claims;
39	        this.people = people;
40	        this.periods = periods;
41	        this.rates = rates;
42	        this.sheets = sheets;
43	        this.audit = audit;
44	    }
45	
46	    @Transactional(readOnly = true)
47	    public List<Claim> list(String sheetId) {
48	        return claims.findBySheetIdOrderByIdDesc(sheetId);
49	    }
50	
51	    @Transactional
52	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
53	        sheets.load(sheetId, user);
54	        // Lock the sheet, so a period closed at the same moment is seen.
55	        sheets.lock(sheetId);
56	        Person person = people.findByIdAndSheetId(personId, sheetId)
57	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
58	        LocalDate on = date != null ? date : sheets.today(sheetId);
59	        refuseIfClosed(sheetId, on);
60	        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount), on, note != null ? note : ""));
61	        record("CLAIM_ADDED", user, person, claim);
62	        return claim;
63	    }
64	
65	    @Transactional
66	    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note) {
67	        sheets.lock(sheetId);
68	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
69	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
70	        LocalDate on = date != null ? date : sheets.today(sheetId);
71	        if (claim.getStatus() != ClaimStatus.DRAFT) {
72	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be edited");
73	        }
74	        refuseIfClosed(sheetId, claim.getDate());
75	        refuseIfClosed(sheetId, on);
76	        claim.setAmount(scaled(amount));
77	        claim.setDate(on);
78	        claim.setNote(note != null ? note : "");
79	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
80	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
81	        record("CLAIM_EDITED", user, person, claim);
82	        return claim;
83	    }
84	
85	    /**
86	     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
87	     * gives the claim the sheet's next number; a voided claim keeps it (the number is never given again).
88	     * Opening records who opened it; that user cannot settle it (403).
89	     * Settling fixes the claim's due at its person's grade's rate in force on the claim's date.
90	     */
91	    @Transactional
92	    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
93	        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers
94	        // and a period closed at the same moment is seen.
95	        Sheet sheet = sheets.lock(sheetId)
96	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
97	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
98	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
99	        refuseIfClosed(sheetId, claim.getDate());
100	        if (!claim.getStatus().canBecome(next)) {
101	            throw new ResponseStatusException(HttpStatus.CONFLICT,
102	                    "A " + claim.getStatus() + " claim cannot become " + next);
103	        }
104	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
105	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
106	        }
107	        Long number = next == ClaimStatus.OPEN ? Long.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
108	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
109	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
110	        claim.setStatus(next);
111	        claim.setNumber(number);
112	        if (next == ClaimStatus.OPEN) {
113	            claim.setOpenedBy(user);
114	        }
115	        List<String> extra = new ArrayList<>();
116	        if (next == ClaimStatus.SETTLED) {
117	            BigDecimal due = rates.inForce(sheetId, person.getGrade(), claim.getDate())
118	                    .map(rate -> claim.getAmount().multiply(rate.getRate())
119	                            .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
120	                    .orElse(null);
121	            claim.setSettledDue(due);
122	            extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
123	        }
124	        record(switch (next) {
125	            case OPEN -> "CLAIM_OPENED";
126	            case SETTLED -> "CLAIM_SETTLED";
127	            case VOID -> "CLAIM_VOIDED";
128	            case DRAFT -> throw new IllegalStateException();
129	        }, user, person, claim, number, extra);
130	        return claim;
131	    }
132	
133	    /** Refuse (423) a change to a claim dated in a closed period. */
134	    private void refuseIfClosed(String sheetId, LocalDate date) {
135	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
136	                .filter(period -> period.isClosed() && period.contains(date))
137	                .findFirst()
138	                .ifPresent(period -> {
139	                    throw new ResponseStatusException(HttpStatus.LOCKED, "The period " + period.getName() + " is closed");
140	                });
141	    }
142	
143	    private void record(String event, String user, Person person, Claim claim) {
144	        record(event, user, person, claim, claim.getNumber(), List.of());
145	    }
146	
147	    /**
148	     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number adds number=&lt;number&gt;; any extra fields follow it.
149	     */
150	    private void record(String event, String user, Person person, Claim claim, Long number, List<String> extra) {
151	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
152	                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
153	        if (number != null) {
154	            fields.add("number=" + number);
155	        }
156	        fields.addAll(extra);
157	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
158	    }
159	
160	    private static BigDecimal scaled(BigDecimal amount) {
161	        return amount.setScale(2, RoundingMode.UNNECESSARY);
162	    }
163	}
