284	export interface Claim {
285	  id: number;
286	  personId: number;
287	  /** Always with two decimals, e.g. "2.50". */
288	  amount: string;
289	  /** yyyy-mm-dd */
290	  date: string;
291	  note: string;
292	  status: ClaimStatus;
293	  /** The sheet's number given when the claim was opened; null for a draft; a voided claim keeps it. */
294	  number: number | null;
295	  /** The due fixed when the claim was settled, two decimals; null if not settled or it had no rate then. */
296	  settledDue: string | null;
297	  /** The user who opened the claim; null while it has not been opened. That user cannot settle it. */
298	  openedBy: string | null;
299	}
