301	/** DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID instead. */
302	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
303	
304	/** The status changes a claim can be asked for, as named in the store's API. */
305	export type ClaimAction = 'open' | 'settle' | 'void';
306	
307	/** Whether the claim counts toward claimed, due-total and every total. */
308	export function counts(claim: Claim): boolean {
309	  return claim.status === 'OPEN' || claim.status === 'SETTLED';
310	}
311	
312	export interface ClaimFields {
313	  amount: string;
314	  date: string;
315	  note: string;
316	}
