318	/** An amount the store accepts: 0 or more, with at most two decimals. */
319	export const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;
320	
321	/** Whole cents of a valid amount, so sums are exact. */
322	export function toCents(amount: string): number {
323	  const [whole, frac = ''] = amount.split('.');
324	  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
325	}
326	
327	export function formatCents(cents: number): string {
328	  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
329	}
