331	// The claims kept on the active sheet, newest first, read from and written to the store.
332	@Injectable({ providedIn: 'root' })
333	export class Claims {
334	  private readonly http = inject(HttpClient);
335	  private readonly session = inject(Session);
336	
337	  readonly all = signal<Claim[]>([]);
338	
339	  /** The claims that count toward the totals: OPEN and SETTLED ones. */
340	  private readonly counted = computed(() => this.all().filter(counts));
341	
342	  /** Each person's claimed, in cents, by person id. */
343	  readonly claimedCents = computed(() => {
344	    const out = new Map<number, number>();
345	    for (const c of this.counted()) out.set(c.personId, (out.get(c.personId) ?? 0) + toCents(c.amount));
346	    return out;
347	  });
348	
349	  readonly totalCents = computed(() => this.counted().reduce((sum, c) => sum + toCents(c.amount), 0));
350	
351	  /** Re-read the store; until it answers no claims are shown, so none is shown out of date. */
352	  async reload(): Promise<void> {
353	    this.all.set([]);
354	    try {
355	      this.all.set(await firstValueFrom(this.http.get<Claim[]>(`${this.sheetUrl()}/claims`, { headers: this.headers() })));
356	    } catch {
357	      this.all.set([]);
358	    }
359	  }
360	
361	  async add(personId: number, fields: ClaimFields): Promise<void> {
362	    const added = await firstValueFrom(
363	      this.http.post<Claim>(`${this.sheetUrl()}/people/${personId}/claims`, this.body(fields), { headers: this.headers() }),
364	    );
365	    this.all.update((list) => [added, ...list]);
366	  }
367	
368	  /**
369	   * The quick-add bar: a DRAFT claim of the amount, dated the sheet's today, for the person of the
370	   * name; the store adds the person first (grade A) when the name is not on the sheet.
371	   */
372	  async quickAdd(name: string, amount: string): Promise<Claim> {
373	    const added = await firstValueFrom(
374	      this.http.post<Claim>(`${this.sheetUrl()}/quick-add`, { name, amount: amount.trim() }, { headers: this.headers() }),
375	    );
376	    this.all.update((list) => [added, ...list]);
377	    return added;
378	  }
379	
380	  async update(id: number, fields: ClaimFields): Promise<void> {
381	    const saved = await firstValueFrom(
382	      this.http.put<Claim>(`${this.sheetUrl()}/claims/${id}`, this.body(fields), { headers: this.headers() }),
383	    );
384	    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
385	  }
386	
387	  /** Move a claim to its next status; the store refuses a change its status does not allow. */
388	  async act(id: number, action: ClaimAction): Promise<void> {
389	    const saved = await firstValueFrom(
390	      this.http.post<Claim>(`${this.sheetUrl()}/claims/${id}/${action}`, null, { headers: this.headers() }),
391	    );
392	    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
393	  }
394	
395	  private body(fields: ClaimFields) {
396	    return { amount: fields.amount.trim(), date: fields.date || null, note: fields.note };
397	  }
398	
399	  private sheetUrl(): string {
400	    const id = this.session.sheetId();
401	    if (!id) throw new Error('no sheet loaded');
402	    return `/api/sheets/${encodeURIComponent(id)}`;
403	  }
404	
405	  private headers(): Record<string, string> {
406	    const user = this.session.user();
407	    if (!user) throw new Error('not signed in');
408	    return { 'X-User': user };
409	  }
410	}
