736	// The signed-in user (a typed name, no password) and the active sheet. Everything else in the app
737	// is kept per sheet.
738	@Injectable({ providedIn: 'root' })
739	export class Session {
740	  private readonly http = inject(HttpClient);
741	
742	  readonly user = signal<string | null>(null);
743	  readonly sheetId = signal<string | null>(null);
744	  /** The active sheet's "today" — use this, never the real clock, for dates in the sheet. */
745	  readonly today = signal<string | null>(null);
746	  /** Counts sheet loads, so per-sheet data re-reads the store on every (re-)load. */
747	  readonly loads = signal(0);
748	  /** True while a sheet is being (re-)loaded, so nothing read from the store before is shown. */
749	  readonly loading = signal(false);
750	
751	  signIn(name: string): void {
752	    this.user.set(name.trim());
753	  }
754	
755	  /** Load (or re-load) a sheet by id; a never-used id starts an empty sheet. */
756	  async loadSheet(id: string): Promise<void> {
757	    const user = this.user();
758	    if (!user) throw new Error('not signed in');
759	    this.loading.set(true);
760	    try {
761	      const sheet = await firstValueFrom(
762	        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id.trim())}/load`, null, {
763	          headers: { 'X-User': user },
764	        }),
765	      );
766	      this.show(sheet);
767	      this.loads.update((n) => n + 1);
768	    } finally {
769	      this.loading.set(false);
770	    }
771	  }
772	
773	  /** Change the active sheet's "today". */
774	  async setToday(today: string): Promise<void> {
775	    const user = this.user();
776	    const id = this.sheetId();
777	    if (!user || !id) throw new Error('no sheet loaded');
778	    const sheet = await firstValueFrom(
779	      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
780	        headers: { 'X-User': user },
781	      }),
782	    );
783	    this.show(sheet);
784	  }
785	
786	  private show(sheet: SheetView): void {
787	    this.sheetId.set(sheet.id);
788	    this.today.set(sheet.today);
789	  }
790	}
